head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gLdMktTp = js_market;
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF10920.xml";
scwin.threadID;
scwin.procJob;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {

};

// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_MASTER.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '4' || scwin.gLdMktTp == '6') {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(panel_mkt, false);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
    }
    if (scwin.gLdMktTp == '1') {
        panel_jongmok.style.visibility = "";
    }

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_FromDate.text = cGetMinusDate2(vCurDate, 365); 	// 일주일전 날짜
    edt_FromDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 발행회사
    dts_CompanyList.DataID = "/DisclosureSearch.do?method=listCompanyCB" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_CompanyList.Reset();
    dts_Jongmok.DataID = "/DisclosureSearch.do?method=getJongmok" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&ISUR_CD=";
    dts_Jongmok.Reset();
};
scwin.fn_list_sync = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/MktActNotice.do?method=listTrdHaltDisclsPublAdm";
    url += "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_FromDate);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_ToDate);
    url += "&ISUR_CD=" + ($c.stf.getObjectValue(txb_isur_cd) == '' ? $c.stf.getObjectValue(cmb_Company) : $c.stf.getObjectValue(txb_isur_cd));
    url += "&ISU_CD=" + $c.stf.getObjectValue(cmb_Jongmok);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.fn_check = function() {
    var checkCnt = 0;
    for (var i = 1; i <= dts_MASTER.getTotalRow(); i++) {
        if (dts_MASTER.getCellData(i, "CHECK") == "T") {
            checkCnt++;
        }
    }
    if (checkCnt <= 0) {
        $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    //선택한 항목이 있는지 check
    if (scwin.fn_check() == true) {
        scwin.fn_SetHeader();
        var gCnt = 0;
        for (var i = 1, k = 1; i <= dts_MASTER.getTotalRow(); i++) {
            if (dts_MASTER.getCellData(i, "CHECK") == "T") {
                dts_UpdateList.insertRow();
                dts_UpdateList.setCellData(k, "ISUR_CD", dts_MASTER.getCellData(i, "ISUR_CD"));
                dts_UpdateList.setCellData(k, "ISU_CD", dts_MASTER.getCellData(i, "ISU_CD"));
                dts_UpdateList.setCellData(k, "REQ_DDTM", dts_MASTER.getCellData(i, "REQ_DDTM"));
                dts_UpdateList.setCellData(k, "TRANSTR_EMP_NO", scwin.gEmpNo);
                k++;
                gCnt++;
            }
        }


        //if (! window.confirm(getMessageParam("MSG-A006", '총 '+gCnt+'건을 저장')) )   return;
        if (!window.confirm("(주의)공시배포 차단을 강제 해제합니다.")) return;
        scwin.procJob = "공시배포 차단내역 강제 해제";
        trs_save.Action = "/MktActNotice.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=updateDisclsPublHaltRetr";
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_UpdateList)";
        trs_save.Post();
    }
};
scwin.fn_SetHeader = function() {
    dts_UpdateList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TRD_HALT_DISCLS_PUBL_ADM_OUT";
    dts_UpdateList.reset();
};
scwin.fn_reload_auto = function() {
    scwin.stopReload();

    //threadID = setInterval('fn_list_sync()',10000);   //10초
    scwin.fn_list_sync();
};
scwin.stopReload = function() {
    clearInterval(scwin.threadID);
};
scwin.getJongmok = function(gubun) {
    dts_Jongmok.DataID = "/DisclosureSearch.do?method=getJongmok" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&ISUR_CD=" + gubun;
    dts_Jongmok.Reset();
};
scwin.fn_clearJongmok = function() {
    $c.stf.setObjectValue(cmb_Company, '');
    $c.stf.setObjectValue(cmb_Jongmok, '');
};
scwin.fn_clearComAbbrv = function() {
    $c.stf.setObjectValue(txb_isur_cd, '');
    $c.stf.setObjectValue(txb_com_abbrv, '');
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_Search_onclick = function() {
    scwin.fn_reload_auto();
};
scwin.dts_MASTER_OnFail = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_MASTER.removeAll();
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "매매거래정지 공시배포 차단 관리", "", "8");
};
scwin.trs_save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_reload_auto();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Init();
    scwin.fn_reload_auto();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.cmb_Company_OnSelChange = function() {
    scwin.getJongmok($c.cp.valueOfIndex(cmb_Company, "VALUE", cmb_Company.getSelectedIndex()));
    scwin.fn_clearComAbbrv();
};
scwin.cmb_Jongmok_OnSelChange = function() {
    scwin.fn_clearComAbbrv();
};
